text:
{
  "questions": [
    {
      "n": 1,
      "start": "Gemäss Ausführungen des Regierungsrates waren im Oktober 2024",
      "end": "Welche Optionen wurden in den letzten Monaten vertieft geprüft?"
    },
    {
      "n": 2,
      "start": "Der Kantonsrat hat die Botschaft B 12 über den Verkauf der Luzerner",
      "end": "Auf welchen Standpunkt stellt sich der Regierungsrat betreffend die Zukunftsszenarien, welche ein hoher Bedarf an Rehaplätzen skizziert?"
    },
    {
      "n": 3,
      "start": "Gilt die Besitzstandswahrung auch nach dem gescheiterten Verkauf der LHM?",
      "end": "Wer garantiert die zweijährige Besitzstandswahrung für das Personal nach der gescheiterten Übernahme durch das Swiss Medical Network?"
    },
    {
      "n": 4,
      "start": "Wie beurteilt der Regierungsrat aus staatspolitischer und aus juristischer Sicht,",
      "end": "Wie wird garantiert, dass der politische Wille des Gesetzgebers in diesem Zusammenhang ausgeübt werden kann?"
    },
    {
      "n": 5,
      "start": "In welcher Form wird der Kantonsrat im weiteren Prozess eingebunden?",
      "end": "Hat der Regierungsrat rechtliche Abklärungen veranlasst, damit das Verhältnis zwischen dem Kantonsratsbeschluss (formeller Entscheid) und der aktuellen Rechtsunsicherheit geklärt wird?"
    },
    {
      "n": 6,
      "start": "Ist dem Regierungsrat bekannt oder liegen ihm Hinweise vor, dass die LHM",
      "end": "Gibt es Anhaltspunkte dafür, dass der Erhalt der LHM von der LUKS AG möglicherweise als unvereinbar mit den unternehmerischen Zielen oder der Eignerstrategie angesehen wurde?"
    },
    {
      "n": 7,
      "start": "Wie beurteilt der Regierungsrat in seiner Rolle als alleiniger Eigentümer der",
      "end": "Sind aus einem allfälligen Missmanagement finanzielle Kosten für die Steuerzahlenden zu erwarten?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Das LUKS hat im Auftrag des Regierungsrates die Vor- und Nachteile der drei Optionen",
      "end": "Weiterführung, die Schliessung und die Suche nach einem neuen Käufer sorgfältig geprüft."
    },
    {
      "n": 2,
      "start": "Ja, der Regierungsrat nimmt seine gesundheitspolitische Verantwortung wahr.",
      "end": "Die Weiterführung durch die BKM ist ein wichtiger Beitrag zu nationalen Rehabilitationsversorgung und zur Sicherung eines hochqualitativen Angebots an einem Standort mit Tradition."
    },
    {
      "n": 3,
      "start": "Für das Personal der LHM gelten nach wie vor die Anstellungsbedingungen des LUKS und",
      "end": "damit Besitzstandswahrung, daran ändert auch das Scheitern des Verkaufs an SMN nichts."
    },
    {
      "n": 4,
      "start": "Die staatspolitische Verantwortung besteht darin, die Ziele der Gesetzesrevision umzusetzen",
      "end": "und das ist auch mit dem Verkauf an die BKM der Fall."
    },
    {
      "n": 5,
      "start": "Die Rechtsordnung sieht keine bedingten Gesetzesänderungen vor.",
      "end": "Der Verkauf der Grundstücke an die BKM oder einen anderen Interessenten bzw. deren Vermietung erfordert somit keine weitere Zustimmung des Kantonsrates."
    },
    {
      "n": 6,
      "start": "Nein, es gibt keine Hinweise auf Vernachlässigung oder Missmanagement.",
      "end": "Das LUKS weist rehabilitationsbedürftige Patientinnen und Patienten und auch zuweisende Ärztinnen und Ärzte nach wie vor auf das Angebot der LHM und die nachweislich sehr hohe Behandlungsqualität hin."
    },
    {
      "n": 7,
      "start": "Der Regierungsrat hat keine Anhaltspunkte für ein Missmanagement.",
      "end": "Durch den Verkauf werden allfällige bei einer Weiterführung (Defizitdeckung, Investitionen) oder Schliessung (Wegfall von Mieteinnahmen, Sozialplan) indirekt für die Steuerzahlenden anfallende Kosten vermieden."
    }
  ],
  "submitter": "Pardini Gianluca",
  "co_signatories": [
    "Galbraith Sofia",
    "Sager Urban",
    "Muff Sara",
    "Horat Marc",
    "Schuler Josef",
    "Meier Anja",
    "Budmiger Marcel",
    "Engler Pia",
    "Zbinden Samuel",
    "Koch Hannes",
    "Heselhaus Sabine",
    "Bolliger Roman",
    "Irniger Barbara",
    "Waldvogel Gian",
    "Kummer Thomas",
    "Brunner Simone",
    "Elmiger Elin",
    "Schneider Andy",
    "Fässler Peter",
    "Pilotto Maria",
    "Steiner Bernhard"
  ],
  "recommendation": "none",
  "reasoning": {
    "start": "Das Luzerner Kantonsspital (LUKS) konnte anfangs Juli 2025 mit der Berner Klinik Montana (BKM) eine Vereinbarung betreffend die Übernahme der Luzerner Höhenklinik Montana AG (LHM) per 1. Januar 2026 erzielen.",
    "end": "Der Regierungsrat ist erfreut, dass mit der BKM – einem im Bereich Rehabilitation erfahrenen und am Standort Montana anerkannten Anbieter – nun doch noch eine zukunftsträchtige Lösung für die LHM und deren Mitarbeitenden gefunden werden konnte."
  }
}
